// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint128 firstAmount, uint128 secondAmount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 a1 = uint256(firstAmount);
        uint256 a2 = uint256(secondAmount);

        vm.deal(actor, a1);
        vm.prank(actor);
        c.Put{value: a1}(0);

        uint256 afterFirst = __invmut_c_Acc_balance(actor);

        vm.deal(actor, a2);
        vm.prank(actor);
        c.Put{value: a2}(0);

        uint256 afterSecond = __invmut_c_Acc_balance(actor);

        assertTrue(afterFirst == a1 && afterSecond == afterFirst + a2);
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
